void decode_bytes(unsigned char *dst, size_t *dst_size, const unsigned char *src, size_t src_size) {
    if (!src || !src_size || !dst_size) {
        return;
    }

    size_t bit_offset = 0;
    size_t decoded_bytes = 0;

    // Calculate the maximum possible decoded size when dst is NULL
    if (!dst) {
        *dst_size = (src_size * 8 + 7) / 8;
        return;
    }

    // Decode the bytes
    for (size_t i = 0; i < src_size; ++i) {
        for (int bit = 0; bit < 8; ++bit) {
            size_t current_bit = (i * 8 + bit) % (8 * sizeof(size_t));
            if (current_bit == 0) {
                decoded_bytes++;
            }
            dst[decoded_bytes - 1] |= ((src[i] >> bit) & 1) << (current_bit);
        }
    }

    *dst_size = decoded_bytes;
}

void decode_filename_format(unsigned char *dst, size_t *dst_size, const unsigned char *src, size_t src_size) {
    if (!dst && dst_size) {
        *dst_size = 0;
        for (size_t i = 0; i < src_size; ++i) {
            *dst_size += (src[i] & 0x80) ? 2 : 1;
        }
        return;
    }

    size_t decoded_bytes = 0;
    for (size_t i = 0; i < src_size; ++i) {
        unsigned char byte = src[i];
        if (byte & 0x80) {
            if (decoded_bytes + 2 <= *dst_size && dst) {
                dst[decoded_bytes++] = (byte & 0x7F);
                dst[decoded_bytes++] = src[i + 1];
            }
            ++i; // Skip the next byte as it is part of a 2-byte sequence
        } else {
            if (decoded_bytes + 1 <= *dst_size && dst) {
                dst[decoded_bytes++] = byte;
            }
        }
    }

    if (dst_size) {
        *dst_size = decoded_bytes;
    }
}

void decode_bytes(unsigned char *dst, size_t *dst_size, const unsigned char *src, size_t src_size) {
    if (dst == NULL) {
        *dst_size = (src_size * 8 + 7) / 8;
        return;
    }

    size_t i, j;
    unsigned char byte = 0;
    size_t bit_count = 0;

    for (i = 0, j = 0; i < src_size; i++) {
        byte = (byte << 8) | src[i];
        bit_count += 8;

        while (bit_count >= 8) {
            dst[j++] = byte >> (bit_count - 8);
            byte &= (1 << (bit_count - 8)) - 1;
            bit_count -= 8;
        }
    }

    if (bit_count > 0) {
        dst[j++] = byte << (8 - bit_count);
    }

    *dst_size = j;
}

void decode_filename_format(unsigned char *dst, size_t *dst_size, const unsigned char *src, size_t src_size) {
    if (dst == NULL) {
        *dst_size = src_size * 2;
        return;
    }

    size_t decoded_size = 0;
    unsigned int bit_offset = 0;
    unsigned char byte = 0;
    unsigned char *current_dst = dst;

    for (size_t i = 0; i < src_size; ++i) {
        unsigned char current_byte = src[i];
        for (int bit = 0; bit < 8; ++bit) {
            if (bit_offset % 8 == 0) {
                byte = 0;
            }
            byte |= ((current_byte >> bit) & 1) << (7 - bit_offset % 8);
            bit_offset++;

            if (bit_offset % 8 == 0) {
                *current_dst++ = byte;
                decoded_size++;
            }
        }
    }

    *dst_size = decoded_size;
}

void decode_filename_format(unsigned char *dst, size_t *dst_size, const unsigned char *src, size_t src_size) {
    size_t i, j;
    size_t bit_offset = 0;
    size_t decoded_size = 0;

    // If destination buffer is NULL, compute the maximum possible size and return
    if (dst == NULL) {
        *dst_size = src_size * 8 / 6;  // 8 bits in a byte, 6 bits in each decoded unit
        return;
    }

    for (i = 0; i < src_size; i++) {
        unsigned char current_byte = src[i];
        size_t remaining_bits = 8 - bit_offset;

        if (remaining_bits >= 6) {
            // Extract 6 bits directly
            unsigned char decoded_byte = (current_byte >> bit_offset) & 0x3F;
            dst[decoded_size++] = decoded_byte;
            bit_offset += 6;
        } else {
            // Split 6 bits across two bytes
            unsigned char decoded_byte = (current_byte >> bit_offset) & 0x3F;
            bit_offset = 6 - remaining_bits;
            i++; // Move to the next byte
            if (i < src_size) {
                decoded_byte |= (src[i] << remaining_bits);
                dst[decoded_size++] = decoded_byte;
                bit_offset = 0;
            }
        }
    }

    *dst_size = decoded_size;
}
